# Logo JMP par defaut ("Fortuna Mining" + "Roxgold Sango" tel que fourni
# dans le document de reference) - modifiable ensuite depuis Parametrage
# sans repasser par une migration.

from django.db import migrations

LOGO_B64 = ""


def creer_logo_defaut(apps, schema_editor):
    Parametre = apps.get_model('accounts', 'Parametre')
    Parametre.objects.get_or_create(
        cle='jmp_logo_base64',
        defaults={'valeur': LOGO_B64, 'description': "JMP - Logo d'en-tete (image encodee base64)"},
    )


def inverse(apps, schema_editor):
    Parametre = apps.get_model('accounts', 'Parametre')
    Parametre.objects.filter(cle='jmp_logo_base64').delete()


class Migration(migrations.Migration):

    dependencies = [
        ('accounts', '0010_remove_rolecustom_readonly_rolecustom_pages_readonly'),
    ]

    operations = [
        migrations.RunPython(creer_logo_defaut, inverse),
    ]
